#pragma once
inline int candidate20Checks(QQuickWindow *window,Bridge &bridge){
 std::function<QQuickItem*(QQuickItem*,const QString&)> findVisual=[&](QQuickItem *root,const QString &name)->QQuickItem*{if(root->objectName()==name)return root;for(auto *child:root->childItems())if(auto *found=findVisual(child,name))return found;return nullptr;};
 int failures=0,requests=0;auto verify=[&](bool ok,const char*n){std::cout<<(ok?"PASS ":"FAIL ")<<n<<std::endl;if(!ok)++failures;};
 bridge.setSelfCheckResponder([&](const QString&,const QVariantMap&){++requests;return QVariantMap{{"ok",false},{"error","No engine mutation permitted in guide fixture"}};});
 QVariantMap installation{{"id","guide-fixture"},{"root","/fixture/WoW"},{"stage","complete"},{"owned",true},{"proton","proton_11"},{"editions",QStringList{"era"}}};
 window->setProperty("session",QVariantMap{{"state",QVariantMap{{"installations",QVariantList{installation}},{"current","guide-fixture"},{"tests",QVariantList{}}}}});window->setProperty("selectedId","guide-fixture");
 QVariantList tiles{QVariantMap{{"appid",qulonglong(3000000001)},{"name","Battle.net"},{"game",true},{"shared",true},{"addon",false}}};window->setProperty("singleTileReady",true);window->setProperty("tiles",tiles);window->setProperty("page","games");window->requestActivate();
 if(!diagnosticWait("guide window active",[&]{return QGuiApplication::focusWindow()==window;}))return 33;
 QTest::qWait(150); // allow page focus initialization before targeting a specific control
 auto *entry=window->findChild<QQuickItem*>("gamesPointerGuide");verify(entry&&entry->isVisible()&&entry->isEnabled(),"existing and new managed games expose scoped pointer guide");if(entry){QMetaObject::invokeMethod(entry,"clicked");}
 verify(diagnosticWait("guide page",[&]{return window->property("page")=="pointerHelp";}),"rendered button handler opens guide");
 for(auto tile:tiles){QTest::qWait(150);auto map=tile.toMap();auto *button=findVisual(window->contentItem(),QString("pointerTile_%1").arg(map["appid"].toULongLong()));verify(button&&button->isVisible(),"sole canonical Battle.net tile listed");if(button){QMetaObject::invokeMethod(button,"clicked");}verify(diagnosticWait("steps",[&]{return window->property("page")=="pointerSteps";})&&window->property("pointerTargetValid").toBool(),"selected tile opens scoped steps");auto *text=window->findChild<QObject*>("pointerTargetText");verify(text&&text->property("text").toString().contains(map["name"].toString())&&text->property("text").toString().contains(map["appid"].toString()),"Battle.net name and exact accepted appid shown");auto *instructions=window->findChild<QObject*>("pointerInstructions");auto s=instructions?instructions->property("text").toString():QString();verify(s.contains("Left Mouse Click")&&s.contains("Mouse")&&s.contains("Keep your deliberate custom layout")&&s.contains("Leave other gamepad"),"mouse/click recommendation preserves other/custom controls");QMetaObject::invokeMethod(window,"back");}
 QMetaObject::invokeMethod(window,"choosePointerTile",Q_ARG(QVariant,tiles[0]));window->setProperty("selectedId","other-fixture");verify(!window->property("pointerTargetValid").toBool(),"changed installation invalidates stale guide target");window->setProperty("selectedId","guide-fixture");window->setProperty("tiles",QVariantList{});verify(!window->property("pointerTargetValid").toBool(),"removed shortcut invalidates stale guide target");verify(requests==0,"guide performs no engine apply/launch/layout writes");bridge.setSelfCheckResponder({});return failures?49:0;
}
